using Astrea.BattleActions;
using LittleLeo.Events;
using UnityEngine;

namespace Astrea.GameStates;

[CreateAssetMenu(fileName = "OnMouseOverNoTargetSelectionAction", menuName = "Data/Battle/Actions/OnMouseOverNoTargetSelectionAction")]
public class OnMouseOverNoTargetSelectionAction : Action
{
	[Header("Events")]
	[SerializeField]
	private VoidEvent OnSetTransitionOutlineLayerYellowHighlightColor;

	private bool highlight;

	private bool alreadyHighlighted;

	protected virtual void OnMouseOver()
	{
		if (!(base.actionInstance == null))
		{
			if (base.actionInstance is DiceInstance)
			{
				OnSetTransitionOutlineLayerYellowHighlightColor.Raise();
			}
			else
			{
				(base.actionInstance as RuneInstance).HighlightRuneInstance();
			}
		}
	}

	protected virtual void OnMouseExit()
	{
		if (!(base.actionInstance == null))
		{
			if (base.actionInstance is DiceInstance)
			{
				(base.actionInstance as DiceInstance).UpdateTransitionOutlineLayer();
			}
			else
			{
				(base.actionInstance as RuneInstance).RemoveHighlightRuneInstance();
			}
		}
	}

	public override void Execute(float d)
	{
		highlight = base.inputManager.IsMouseOrTouchOnCastRange();
		if (highlight && !alreadyHighlighted)
		{
			OnMouseOver();
			alreadyHighlighted = true;
		}
		if (alreadyHighlighted && !highlight)
		{
			OnMouseExit();
			alreadyHighlighted = false;
		}
	}
}
